package org.humanjourney.core.advancement;
import java.util.*;
import net.minecraft.server.MinecraftServer;
import net.minecraft.advancements.AdvancementHolder;
import net.minecraft.resources.ResourceLocation;
import org.humanjourney.core.geography.GeographyRoles;
/** Reads only native advancement visibility/progress, never getOrStartProgress/award/revoke/scores. */
public final class NativeServer {
 private static MinecraftServer owner;private static UUID session=UUID.randomUUID();private static long sequence,checked=-1;
 private record Sent(int entity,String json){}private static final Map<UUID,Sent> clients=new HashMap<>();
 public static void clear(){owner=null;session=UUID.randomUUID();sequence=0;checked=-1;clients.clear();}
 public static void validate(NativePresentation model,java.util.function.Function<String,AdvancementHolder> lookup){for(var tab:model.tabs()){var root=lookup.apply(tab.root());if(root==null||root.value().parent().isPresent()||root.value().display().isEmpty())throw new IllegalArgumentException("not a displayed native root: "+tab.root());for(String id:tab.ids()){var holder=lookup.apply(id);if(holder==null||holder.value().display().isEmpty())throw new IllegalArgumentException("advancement lacks native display: "+id);var seen=new HashSet<String>();var current=holder;while(current.value().parent().isPresent()){if(!seen.add(current.id().toString())||seen.size()>512)throw new IllegalArgumentException("invalid native ancestry "+id);current=lookup.apply(current.value().parent().get().toString());if(current==null)throw new IllegalArgumentException("missing native parent "+id);}if(!current.id().toString().equals(tab.root()))throw new IllegalArgumentException("cross-root link/layout unsupported: "+id+" belongs to "+current.id()+", expected "+tab.root());}}}
 public static void tick(MinecraftServer server){if(owner!=server){clear();owner=server;}if(server.getTickCount()%20!=0)return;var state=NativeStore.state();if(checked!=state.revision()){checked=state.revision();try{validate(state.model(),id->server.getAdvancements().get(ResourceLocation.parse(id)));}catch(IllegalArgumentException e){NativeStore.reject(state.source(),state.source()+": "+e.getMessage());com.mojang.logging.LogUtils.getLogger().error("[HJ Core] Native presentation vanilla fallback: {}",NativeStore.state().error());state=NativeStore.state();checked=state.revision();}}var online=server.getPlayerList().getPlayers();var ids=new HashSet<UUID>();for(var player:online){ids.add(player.getUUID());var view=NativePresentation.empty();if(!state.model().tabs().isEmpty()&&GeographyRoles.from(player.getTags()).participant()&&player.getAdvancements() instanceof NativeVisibility visibility){var drawn=new HashSet<String>();for(var holder:visibility.hjVisible()){var display=holder.value().display();var progress=visibility.hjProgress().get(holder);if(display.isPresent()&&(!display.get().isHidden()||progress!=null&&progress.isDone()))drawn.add(holder.id().toString());}view=state.model().visible(drawn);}String json=view.json();var prev=clients.get(player.getUUID());if(prev!=null&&prev.entity==player.getId()&&prev.json.equals(json))continue;boolean sent=true;for(var frame:NativePackets.frames(session,++sequence,view))if(!NativeNetwork.send(frame,player)){sent=false;break;}if(sent)clients.put(player.getUUID(),new Sent(player.getId(),json));}clients.keySet().retainAll(ids);}
 private NativeServer(){}
}
